import sys

def minimalBases(classes: list) -> list:
    """
    Returns all classes without subclasses as a list.
    """
    classes_with_subclasses = defaultdict(set)
    modules = [__import__(name) for name in sys.modules]

    for module in modules:
        for name, obj in inspect.getmembers(module, inspect.isclass):
            for subclass in inspect.getmro(obj)[1:]:
                classes_with_subclasses[subclass].add(obj)

    minimal_bases = []
    for cls, subclasses in classes_with_subclasses.items():
        if not subclasses:
            minimal_bases.append(cls)

    return minimal_bases

