def _dictsum(dicts: List[Dict[str, int]]) -> Dict[str, int]:
    """
    Sum values with the same key in the dictionaries. And return a new dictionary.
    Example:
        given two dictionaries: dict1: {'a': 1, 'b': 2}, dict2: {'a': 5, 'b': 0}
        return a dictionary: {'a': 6, 'b': 2}
    Returns: dict
    """
    result_dict = {}
    for dictionary in dicts:
        for key, value in dictionary.items():
            if key in result_dict:
                result_dict[key] += value
            else:
                result_dict[key] = value
    return result_dict

