def split(s: str, platform: str = 'this') -> List[str]:
    if platform == 'this':
        platform = os.name

    if platform == 'posix':
        pattern = re.compile(r'\s+')
    elif platform == 'nt':
        pattern = re.compile(r'\s+')
    else:
        raise ValueError(f"Unsupported platform: {platform}")

    return pattern.split(s)

