from typing import List
import datetime
import re
from typing import Optional

def parse_frequency(frequency: Optional[str]) -> Optional[datetime.timedelta]:
    if frequency is None or frequency == 'always':
        return None

    # Regular expression to match the frequency string
    pattern = re.compile(r'^(\d+)\s*(seconds|minutes|hours|days|weeks)$')
    match = pattern.match(frequency)

    if not match:
        return None

    number = int(match.group(1))
    unit = match.group(2)

    if unit == 'seconds':
        return datetime.timedelta(seconds=number)
    elif unit == 'minutes':
        return datetime.timedelta(minutes=number)
    elif unit == 'hours':
        return datetime.timedelta(hours=number)
    elif unit == 'days':
        return datetime.timedelta(days=number)
    elif unit == 'weeks':
        return datetime.timedelta(weeks=number)
    else:
        return None

