class Bookmarks:
    def __init__(self):
        self.categories = {}

    def add_category(self, name: str, bookmarks: list = None):
        if bookmarks is None:
            bookmarks = []
        self.categories[name] = bookmarks

    def add_bookmark(self, category: str, title: str, url: str):
        if category not in self.categories:
            self.categories[category] = []
        self.categories[category].append({'title': title, 'url': url})

    def search(self, query: str) -> list:
        results = []
        for category in self.categories.values():
            for bookmark in category:
                if query.lower() in bookmark['title'].lower() or query.lower() in bookmark['url'].lower():
                    results.append(bookmark)
        return results

